# Minimized from D2 v0.9.0 nesting_power: restored grid-actor crossing
# must route inside the detached sequence scope before parent reinjection.
sequence: {
  shape: sequence_diagram
  with -> another.x -> actor
  actor: {
    grid-rows: 2
    grid-columns: 2
    grid-gap: 0
    first
    second
    grid: {
      grid-rows: 3
      1 -> 2 -> 3
    }
    notes: {
      shape: sequence_diagram
      continue -> nesting
    }
  }
  actor.notes.nesting -> another.x
}
outside -> sequence.with
